// Direct-publication batch filter for nested category references on the front endpoint (Product.categories, Product.primaryCategory) - returns the subset of candidate IDs whose own (category, channel) listing is published AND whose own row carries is_published=TRUE - does NOT walk the ancestor chain - affiliation listings don't need breadcrumb integrity; callers that need it use ListFullyVisible*
func (q *Queries) ListPublishedCategoryIDsForChannelFiltered(ctx context.Context, arg ListPublishedCategoryIDsForChannelFilteredParams) ([]uuid.UUID, error) {
	rows, err := q.db.QueryContext(ctx, listPublishedCategoryIDsForChannelFiltered, pq.Array(arg.CategoryIds), arg.ChannelID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

